import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"6.2 设备撤销与安全迁移","description":"设备丢失后可立即失效，更换设备时数据完整转移。","frontmatter":{"title":"6.2 设备撤销与安全迁移","description":"设备丢失后可立即失效，更换设备时数据完整转移。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6/6-2.md","filePath":"delivery/stage-6/6-2.md","lastUpdated":null}'),r={name:"delivery/stage-6/6-2.md"};function o(n,e,s,d,_,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_6-2-设备撤销与安全迁移" tabindex="-1">6.2 设备撤销与安全迁移 <a class="header-anchor" href="#_6-2-设备撤销与安全迁移" aria-label="Permalink to &quot;6.2 设备撤销与安全迁移&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让设备丢失、更换或迁移时可以安全撤销和转移，撤销后旧设备不能再审批、接管或查看数据。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>提供立即撤销设备的入口，撤销后所有会话和审批权限同时失效。</li><li>撤销后检查旧设备不能继续接收任务、查看产物或执行操作。</li><li>更换设备时使用安全迁移流程，迁移后核对任务、产物、记忆和授权。</li><li>按设备能力分配任务：桌面操作交给有桌面能力的设备，手机只做查看、审批和接管。</li><li>记录撤销和迁移过程，方便用户核对。</li><li>做一次设备丢失演练：从撤销到确认旧设备失效，整个过程可完成。</li></ol>',5)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
